def h(a, x):
    lo, hi = 0, len(a) - 1
    r = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            r = mid
            hi = mid - 1
    return r
