import sqlite3
DDL = '''
CREATE TABLE Dept (DId INT PRIMARY KEY, DName TEXT);
CREATE TABLE Emp (EId INT PRIMARY KEY, EName TEXT, DId INT REFERENCES Dept(DId) ON DELETE SET NULL);
CREATE TABLE Proj (PId TEXT PRIMARY KEY, PName TEXT, DId INT REFERENCES Dept(DId) ON DELETE CASCADE);
CREATE TABLE Task (TId TEXT PRIMARY KEY, PId TEXT REFERENCES Proj(PId) ON DELETE NO ACTION, Hours INT);
INSERT INTO Dept VALUES (10,'Sales'),(20,'Research'),(30,'Legal');
INSERT INTO Emp VALUES (1,'Ravi',10),(2,'Sita',20),(3,'Tara',20),(4,'Uma',30),(5,'Vik',NULL);
INSERT INTO Proj VALUES ('P1','Alpha',10),('P2','Beta',20),('P3','Gamma',30),('P4','Delta',30);
INSERT INTO Task VALUES ('T1','P1',5),('T2','P2',8),('T3','P2',3);
'''
def run(sql):
    c = sqlite3.connect(':memory:'); c.executescript(DDL); c.execute('PRAGMA foreign_keys=ON')
    try: c.execute(sql); ok = True
    except sqlite3.IntegrityError: ok = False
    return c, ok
